const app=document.querySelector('#app');
const ACTION_META={move:['MOVE','↗','Reposition or ram a bot'],blast:['BLAST','✦','Fire until a bot or wall'],shield:['SHIELD','⬡','Block one incoming blast'],hack:['HACK','⌁','Disable an adjacent shield'],overcharge:['OVERCHARGE','ϟ','Gain +1 energy']};
const DIR_ICON={up:'↑',down:'↓',left:'←',right:'→'};
const DIR_VEC={up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}};
const PALETTE=['#67f7a1','#62d9ff','#ff6b9e','#ffd166','#b58cff','#ff965c','#55f0df','#f06cff'];
const state={code:localStorage.rbCode||'',playerId:localStorage.rbPlayerId||'',room:null,error:'',notice:'',actionType:'move',dir:'up',poll:null,heartbeat:null,lastTurnKey:'',fx:null,fxTimer:null};
const api=async(op,data)=>{let url='/.netlify/functions/game';let options={headers:{'content-type':'application/json'}};if(data){options.method='POST';options.body=JSON.stringify({op,...data})}else{const [name,query='']=op.split('?');url+=`?op=${encodeURIComponent(name)}${query?'&'+query:''}`}const res=await fetch(url,options);const j=await res.json();if(!res.ok)throw new Error(j.error||'Request failed');return j};
function saveSession(){localStorage.rbCode=state.code;localStorage.rbPlayerId=state.playerId}
function stopTimers(){if(state.poll)clearInterval(state.poll);if(state.heartbeat)clearInterval(state.heartbeat);state.poll=null;state.heartbeat=null}
function startTimers(){stopTimers();state.poll=setInterval(refresh,700);state.heartbeat=setInterval(heartbeat,5000)}
function clearSession(notice=''){localStorage.removeItem('rbCode');localStorage.removeItem('rbPlayerId');state.code='';state.playerId='';state.room=null;state.notice=notice;state.error='';stopTimers();render()}
function me(){return state.room?.players.find(p=>p.id===state.playerId)}
function host(){return state.room?.hostId===state.playerId}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setError(e){state.error=e?.message||String(e);render()}
function maybeFx(room){const t=room?.lastTurn;if(!t)return;const key=`${room.code}:${t.round}:${t.resolvedAt}`;if(key===state.lastTurnKey)return;state.lastTurnKey=key;state.fx=t;clearTimeout(state.fxTimer);state.fxTimer=setTimeout(()=>{state.fx=null;render()},3000)}
async function refresh(){if(!state.code)return;try{const j=await api(`state?code=${encodeURIComponent(state.code)}`);state.room=j.room;state.error='';if(!me()&&state.room.phase!=='abandoned'){clearSession('Your connection to that arena ended.');return}maybeFx(j.room);render()}catch(e){if(/Room not found/i.test(e.message))clearSession('That arena is no longer available.');else setError(e)}}
async function heartbeat(){if(!state.code||!state.playerId)return;try{const j=await api('heartbeat',{code:state.code,playerId:state.playerId});state.room=j.room;state.error='';if(!me()){clearSession('You were disconnected from the arena.');return}maybeFx(j.room);render()}catch(e){if(/Player not found|Room not found/i.test(e.message))clearSession('You were disconnected from the arena.')}}
async function create(){try{const name=document.querySelector('#name').value;const j=await api('create',{name});state.playerId=j.playerId;state.code=j.room.code;state.room=j.room;state.notice='';saveSession();startTimers();render()}catch(e){setError(e)}}
async function join(){try{const name=document.querySelector('#name').value;const code=document.querySelector('#roomCode').value.toUpperCase();const j=await api('join',{name,code});state.playerId=j.playerId;state.code=code;state.room=j.room;state.notice='';saveSession();startTimers();render()}catch(e){setError(e)}}
async function ready(){try{const j=await api('ready',{code:state.code,playerId:state.playerId,ready:!me().ready});state.room=j.room;render()}catch(e){setError(e)}}
async function start(){try{const j=await api('start',{code:state.code,playerId:state.playerId});state.room=j.room;render()}catch(e){setError(e)}}
async function act(){try{const action={type:state.actionType};if(['move','blast','hack'].includes(state.actionType))action.dir=state.dir;const j=await api('action',{code:state.code,playerId:state.playerId,action});state.room=j.room;maybeFx(j.room);render()}catch(e){setError(e)}}
async function rematch(){try{const j=await api('rematch',{code:state.code,playerId:state.playerId});state.room=j.room;state.lastTurnKey='';render()}catch(e){setError(e)}}
async function returnLobby(){try{const j=await api('returnLobby',{code:state.code,playerId:state.playerId});state.room=j.room;state.lastTurnKey='';render()}catch(e){setError(e)}}
async function leaveArena(){const active=state.room?.phase==='playing';const msg=active?'Leave this match? You will be removed from the arena.':'Leave this room?';if(!window.confirm(msg))return;try{if(state.code&&state.playerId)await api('leave',{code:state.code,playerId:state.playerId})}catch{}clearSession(active?'You left the arena.':'You left the room.')}
function err(){return state.error?`<div class="error">${esc(state.error)}</div>`:''}
function notice(){return state.notice?`<div class="notice">${esc(state.notice)}</div>`:''}
function home(){return `<div class="shell home-shell"><div class="brand"><div class="eyebrow">UNDERGROUND ROBOT COMBAT</div><h1>ROBO <span>BREAKERS</span></h1><div class="tagline">OUTTHINK. OUTBLAST. OUTLAST.</div></div><div class="panel home">${err()}${notice()}<div class="mission"><b>LAST BOT STANDING</b><span>2–8 pilots choose commands in secret. Every move resolves together.</span></div><label>PILOT NAME<input id="name" maxlength="16" placeholder="Your pilot name" value="Joe"></label><button class="btn primary big" id="create">CREATE ARENA</button><div class="divider"><span>OR JOIN A FIGHT</span></div><div class="row"><input id="roomCode" maxlength="4" placeholder="ROOM CODE" style="flex:1;text-transform:uppercase"><button class="btn" id="join">JOIN</button></div><div class="rules-grid"><span>↗ <b>MOVE</b><small>Position / ram</small></span><span>✦ <b>BLAST</b><small>Deal damage</small></span><span>⬡ <b>SHIELD</b><small>Block blasts</small></span><span>⌁ <b>HACK</b><small>Break shields</small></span><span>ϟ <b>OVERCHARGE</b><small>Gain energy</small></span></div></div></div>`}
function lobby(){const r=state.room;return `<div class="shell"><div class="brand compact"><div class="eyebrow">PRIVATE ARENA</div><h1>ROBO <span>BREAKERS</span></h1></div><div class="panel lobby">${err()}<div class="roomhead"><div><div class="tag">ROOM CODE</div><div class="code">${r.code}<button class="copycode" id="copyCode">COPY</button></div></div><button class="btn danger-btn" id="leave">LEAVE</button></div><div class="lobby-title">PILOTS <span>${r.players.length}/8</span></div><div class="players">${r.players.map((p,i)=>playerCard(p,i,r)).join('')}</div><div class="row lobby-actions">${!host()?`<button class="btn ${me()?.ready?'good':''}" id="ready">${me()?.ready?'READY ✓':'READY UP'}</button>`:''}${host()?`<button class="btn primary" id="start" ${r.players.length<2?'disabled':''}>START MATCH</button>`:''}</div><p class="rules">${host()?'Start when every challenger is ready.':'Ready up. The host launches the match.'}</p></div></div>`}
function playerCard(p,i,r){const c=PALETTE[i%PALETTE.length];return `<div class="player lobby-player" style="--pc:${c}"><div class="mini-bot">${botSvg(c)}</div><div><b>${esc(p.name)}${p.id===r.hostId?' <span class="crown">HOST</span>':''}</b><div class="status">${p.id===r.hostId?'ARENA OWNER':p.ready?'● READY':'○ STANDBY'}</div></div></div>`}
function botSvg(c){return `<svg viewBox="0 0 120 120" aria-hidden="true"><g fill="none" stroke-linejoin="round"><path d="M39 16h42l7 10-5 19H37l-5-19z" fill="#07111d" stroke="${c}" stroke-width="4"/><path d="M47 27h26l-4 8H51z" fill="${c}"/><path d="M31 42 13 50l6 28 18-6 5-28z" fill="${c}22" stroke="${c}" stroke-width="4"/><path d="m89 42 18 8-6 28-18-6-5-28z" fill="${c}22" stroke="${c}" stroke-width="4"/><path d="M39 43h42l8 35-15 13H46L31 78z" fill="${c}18" stroke="${c}" stroke-width="5"/><path d="M48 51h24l6 18-18 12-18-12z" fill="#07111d" stroke="${c}" stroke-width="3"/><circle cx="60" cy="64" r="8" fill="${c}" opacity=".9"/><path d="M46 91 35 111h17l8-18m14-2 11 20H68l-8-18" fill="${c}18" stroke="${c}" stroke-width="4"/><path d="M22 77 13 96m85-19 9 19" stroke="${c}" stroke-width="6" stroke-linecap="round"/></g></svg>`}
function previewMap(){const map=new Map(),r=state.room,p=me();if(!r||!p||p.lockedIn||!p.alive)return map;const mark=(x,y,cls)=>{if(x>=0&&y>=0&&x<r.boardSize&&y<r.boardSize)map.set(`${x},${y}`,[...(map.get(`${x},${y}`)||[]),cls])};const d=DIR_VEC[state.dir];if(state.actionType==='move'){mark(p.x+d.x,p.y+d.y,'preview-move')}else if(state.actionType==='blast'){let x=p.x+d.x,y=p.y+d.y;while(x>=0&&y>=0&&x<r.boardSize&&y<r.boardSize){mark(x,y,'preview-blast');if(r.players.some(q=>q.alive&&q.x===x&&q.y===y)){mark(x,y,'preview-hit');break}x+=d.x;y+=d.y}}else if(state.actionType==='hack'){mark(p.x+d.x,p.y+d.y,'preview-hack');if(r.players.some(q=>q.alive&&q.x===p.x+d.x&&q.y===p.y+d.y))mark(p.x+d.x,p.y+d.y,'preview-hit')}else if(state.actionType==='shield'){mark(p.x,p.y,'preview-shield')}else if(state.actionType==='overcharge'){mark(p.x,p.y,'preview-charge')}return map}
function fxMap(){const map=new Map(),t=state.fx;if(!t)return map;const add=(x,y,cls)=>{if(x==null||y==null)return;map.set(`${x},${y}`,[...(map.get(`${x},${y}`)||[]),cls])};for(const v of t.visuals||[]){if(v.type==='blast'){for(const pt of v.path||[])add(pt.x,pt.y,'fx-blast');if(v.targetId&&v.path?.length){const pt=v.path[v.path.length-1];add(pt.x,pt.y,v.blocked?'fx-block':'fx-hit')}}if(v.type==='hack'&&v.target)add(v.target.x,v.target.y,v.success?'fx-hack':'fx-miss');if(v.type==='shield'&&v.at)add(v.at.x,v.at.y,v.active?'fx-shield':'fx-hack');if(v.type==='overcharge'&&v.at)add(v.at.x,v.at.y,'fx-charge');if(v.type==='move'&&v.to)add(v.to.x,v.to.y,'fx-move')}return map}
function board(){const r=state.room,preview=previewMap(),fx=fxMap();let tiles='';for(let y=0;y<r.boardSize;y++){for(let x=0;x<r.boardSize;x++){const p=r.players.find(q=>q.alive&&q.x===x&&q.y===y);const idx=p?r.players.findIndex(q=>q.id===p.id):-1;const classes=[...(preview.get(`${x},${y}`)||[]),...(fx.get(`${x},${y}`)||[])].join(' ');tiles+=`<div class="tile ${classes}" data-x="${x}" data-y="${y}">${p?botPiece(p,idx):''}</div>`}}return `<div class="arena-wrap"><div class="arena-label"><span>ARENA // ${r.boardSize}×${r.boardSize}</span><span>ROUND ${r.round}</span></div><div class="board" style="grid-template-columns:repeat(${r.boardSize},1fr)">${tiles}</div><div class="arena-hint">${previewLegend()}</div></div>`}
function previewLegend(){if(me()?.lockedIn)return 'COMMAND LOCKED // waiting for remaining pilots';const m=ACTION_META[state.actionType];return `${m[0]} ${['move','blast','hack'].includes(state.actionType)?DIR_ICON[state.dir]:''} // ${m[2]}`}
function botPiece(p,i){const c=PALETTE[i%PALETTE.length];const facing=p.id===state.playerId&&['move','blast','hack'].includes(state.actionType)?state.dir:'up';return `<div class="bot ${p.id===state.playerId?'me':''}" style="--pc:${c}" title="${esc(p.name)}"><div class="facing facing-${facing}">▲</div><div class="bot-art">${botSvg(c)}</div><div class="bot-name">${esc(p.name)}</div><div class="hpbar">${Array.from({length:3},(_,n)=>`<i class="${n<p.hp?'on':''}"></i>`).join('')}</div></div>`}
function previewText(){const m=ACTION_META[state.actionType];return `${m[0]}${['move','blast','hack'].includes(state.actionType)?' '+DIR_ICON[state.dir]:''} — ${m[2]}`}
function game(){const r=state.room,m=me(),locked=m?.lockedIn;return `<div class="shell game-shell"><div class="game-top"><div><div class="tag">ROOM ${r.code}</div><h2>ROUND <span>${r.round}</span></h2></div><div class="top-actions"><div class="pilot-hud"><b>${esc(m?.name||'')}</b><span>${'♥'.repeat(m?.hp??0)}${'♡'.repeat(Math.max(0,3-(m?.hp??0)))}</span><em>ϟ ${m?.energy??0}</em></div><button class="btn danger-btn leave-match" id="leave">LEAVE MATCH</button></div></div>${err()}<div class="gamegrid">${board()}<aside class="side"><div class="panel command"><div class="panel-kicker">COMMAND CONSOLE</div><h3>${locked?'COMMAND LOCKED':'CHOOSE YOUR MOVE'}</h3><div class="status">${locked?'Waiting for rival bots…':'Your command stays secret until execution.'}</div><div class="actions">${Object.entries(ACTION_META).map(([k,m])=>`<button class="btn action ${state.actionType===k?'selected':''}" data-action="${k}" ${locked||!me()?.alive?'disabled':''}><strong>${m[1]}</strong><span>${m[0]}</span></button>`).join('')}</div>${['move','blast','hack'].includes(state.actionType)?`<div class="dirpad"><button class="btn up ${state.dir==='up'?'dirsel':''}" data-dir="up">↑</button><button class="btn left ${state.dir==='left'?'dirsel':''}" data-dir="left">←</button><button class="btn down ${state.dir==='down'?'dirsel':''}" data-dir="down">↓</button><button class="btn right ${state.dir==='right'?'dirsel':''}" data-dir="right">→</button></div>`:''}<div class="command-preview">${previewText()}</div><button class="btn primary lock" id="lock" ${locked||!m?.alive?'disabled':''}>${m?.alive?(locked?'LOCKED':'LOCK IN COMMAND'):'DECOMPILED'}</button></div><div class="panel roster"><div class="panel-kicker">PILOTS</div>${r.players.map((p,i)=>`<div class="roster-row" style="--pc:${PALETTE[i%PALETTE.length]}"><span class="dot"></span><b>${esc(p.name)}${p.id===r.hostId?' <small class="host-chip">HOST</small>':''}</b><span>${p.alive?`${'♥'.repeat(p.hp)} · ϟ${p.energy} ${p.lockedIn?'· 🔒':''}`:'☠ DECOMPILED'}</span></div>`).join('')}</div><div class="panel combat"><div class="panel-kicker">SYSTEM FEED</div><div class="log">${r.log.slice(-7).reverse().map(x=>`<div>${formatLog(x)}</div>`).join('')}</div></div></aside></div>${state.fx?executeOverlay(state.fx,r):''}</div>`}
function formatLog(x){return esc(x).replace(/HAS BEEN DECOMPILED/g,'<b class="danger">HAS BEEN DECOMPILED</b>').replace(/WINNER:/g,'<b class="gold">WINNER:</b>').replace(/is now the host/g,'<b class="goodtext">is now the host</b>')}
function visualResult(a,t){const v=(t.visuals||[]).find(x=>x.actorId===a.id&&x.type===a.action?.type);if(!v)return'';if(v.type==='blast')return v.hit?(v.blocked?'BARRIER BLOCKED':'TARGET HIT'):'MISS';if(v.type==='hack')return v.success?'SIGNAL BREACH':'NO TARGET';if(v.type==='shield')return v.active?'BARRIER ONLINE':'SHIELD DISABLED';if(v.type==='overcharge')return'CORE +1';if(v.type==='move')return v.blocked?'MOVEMENT BLOCKED':v.pushedId?'RAM IMPACT':'THRUST MOVE';return''}
function executeOverlay(t,r){return `<div class="execute-overlay"><div class="execute-card"><div class="execute-label">ROUND ${t.round} // COMMANDS REVEALED</div><div class="execute-title">EXECUTE</div><div class="reveal-list">${t.actions.map(a=>{const idx=r.players.findIndex(p=>p.id===a.id),c=PALETTE[(idx<0?0:idx)%PALETTE.length],m=ACTION_META[a.action?.type]||['?','?',''];return `<div style="--pc:${c}"><span>${esc(a.name)}</span><b>${m[1]} ${m[0]} ${a.action?.dir?DIR_ICON[a.action.dir]:''}</b><em>${visualResult(a,t)}</em></div>`}).join('')}</div><div class="execute-events">${t.events.filter(e=>!/^ROUND /.test(e)).slice(0,4).map(e=>`<span>${esc(e)}</span>`).join('')}</div></div></div>`}
function interrupted(){const r=state.room;return `<div class="shell"><div class="brand compact"><div class="eyebrow">ARENA INTERRUPTED</div><h1>ROBO <span>BREAKERS</span></h1></div><div class="panel interrupted">${err()}<div class="signal-icon">⚠</div><h2>OPPONENT LEFT THE ARENA</h2><p>${esc(r.interruptReason||'A pilot disconnected from the match.')}</p><div class="host-transfer">${host()?'You now control this room as host.':'Waiting for the host to reset the room.'}</div><div class="winner-actions">${host()?'<button class="btn primary big" id="returnLobby">RETURN TO LOBBY</button>':''}<button class="btn" id="leave">RETURN TO TITLE</button></div></div></div>`}
function finished(){const r=state.room,winners=r.players.filter(p=>r.winnerIds.includes(p.id));return `<div class="shell"><div class="brand"><div class="eyebrow">MATCH COMPLETE</div><h1>ROBO <span>BREAKERS</span></h1></div><div class="panel winner">${err()}<div class="trophy">🏆</div><h2>${esc(winners.map(w=>w.name).join(' & ')||'DRAW')}</h2><p class="victory-line">LAST BOT STANDING</p><div class="scoreboard">${[...r.players].sort((a,b)=>b.eliminations-a.eliminations||b.damageDealt-a.damageDealt).map((p,i)=>`<div><span>#${i+1} ${esc(p.name)}</span><b>${p.eliminations} KO</b><em>${p.damageDealt} DMG</em></div>`).join('')}</div><div class="winner-actions">${host()?'<button class="btn primary big" id="rematch">REMATCH</button>':'<p>Waiting for host…</p>'}<button class="btn" id="leave">LEAVE</button></div></div></div>`}
function render(){app.innerHTML=!state.room?home():state.room.phase==='lobby'?lobby():state.room.phase==='playing'?game():state.room.phase==='interrupted'?interrupted():state.room.phase==='finished'?finished():home();bind()}
function bind(){document.querySelector('#create')?.addEventListener('click',create);document.querySelector('#join')?.addEventListener('click',join);document.querySelector('#leave')?.addEventListener('click',leaveArena);document.querySelector('#ready')?.addEventListener('click',ready);document.querySelector('#start')?.addEventListener('click',start);document.querySelector('#lock')?.addEventListener('click',act);document.querySelector('#rematch')?.addEventListener('click',rematch);document.querySelector('#returnLobby')?.addEventListener('click',returnLobby);document.querySelector('#copyCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.code);const b=document.querySelector('#copyCode');if(b){b.textContent='COPIED';setTimeout(()=>{if(document.querySelector('#copyCode'))document.querySelector('#copyCode').textContent='COPY'},1200)}}catch{setError(new Error('Could not copy room code.'))}});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{state.actionType=b.dataset.action;render()}));document.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('click',()=>{state.dir=b.dataset.dir;render()}))}
if(state.code&&state.playerId){refresh().then(()=>{if(state.room)startTimers()})}else render();
